/*
* This file contains the pre-calcuated CactusKev lookups for hands based on the rules
* of "Pai-Gow Poker." If you're not familiar with the game or its rules, you can
* read about both here:
* 
* https://wizardofodds.com/games/pai-gow-poker/
*/

import { IPaiGowPokerEnums } from "../types/enums/ipaigowpokerenums.js";
import { CactusKevEnums } from "./cactuskev.js";

/*
* "Pai-Gow Poker" uses a standard 52-card deck with a JOKER.
* The Joker can be used to complete a straight, a flush, or a
* straight flush, otherwise it counts as an Ace.
* 
* Remembering this definition:
*
* +--------+--------+--------+--------+
* |xxbbbbbb|bbbbbbbb|cdhsrrrr|xxpppppp|
* +--------+--------+--------+--------+
*
* we can add the Joker, which has all four suits, and its own rank
*
* xx*AKQJT 98765432 CDHSrrrr xxpppppp
* 00100000 00000000 11111101 00101001    Joker
* 
* This also creates a unique hand - the FIVE ACES hand.  It is considered higher-ranked
* than a Royal Flush, due to it's uniqueness.  Therefore all the outcome values below in
* the arrays have been incremented by 1 to reflect this.
*/
CactusKevEnums.CARD_VALUES["*"] = 0x2000FD29;

