const HAND_NAMES = (eqv: number): string => {
    if (eqv == 1) return "Five Aces";
    if (eqv == 2) return "Royal Flush";
    if (eqv <= 11) return "Straight Flush";
    if (eqv <= 167) return "Four of a Kind";
    if (eqv <= 323) return "Full House";
    if (eqv <= 1600) return "Flush";
    if (eqv <= 1610) return "Straight";
    if (eqv <= 2468) return "Three of a Kind";
    if (eqv <= 3326) return "Two Pair";
    if (eqv <= 6186) return "Pair";
    return "High Card";
};

/*
** CactusKev equivs for two-card hands,  The idea is that "QJ" is just the same as "QJ432" for comparison values.
** In Paigow this is okay, since it wouldn't really happen (if someone had QQJJ432 they'd split it JJ/QQ432).  But even
** if they split it QJ/QJ432 this is a valid split by the rules.  it's like saying 15 < 15.0000000001.
*/

